-- Ejecutar DESPUÉS del script 1. Se puede repetir: actualiza sin duplicar. Todo el contenido se edita luego desde el panel.
-- Fuentes: Prompt maestro v1 (2026-10-10) y carpeta Proyectos.zip. Estado de validación indicado en cada servicio.

delete from services where slug in ('ingenieria-control-proteccion','diseno-circuitos-secundarios','diseno-tableros','armado-tableros','tendido-conexionado','configuracion-ieds','pruebas-funcionales','pruebas-proteccion','automatizacion','comisionamiento','puesta-en-servicio','mantenimiento-diagnostico') and validation_status is distinct from 'confirmed';
delete from technologies where name in ('ABB','Hitachi Energy','Hitachi','Siemens','SEL','GE','Omicron','Siemens ');
insert into technologies(name,description,logo_url) values ('ABB','Experiencia declarada. Familia declarada: Relion.','/tecnologias/abb.svg'),('Hitachi Energy','Experiencia declarada.','/tecnologias/hitachi-energy.svg'),('Siemens','Experiencia declarada. Familia declarada: SIPROTEC.','/tecnologias/siemens.svg'),('SEL','Experiencia declarada. Familia declarada: SEL-351.','/tecnologias/sel.svg'),('GE','Experiencia declarada. Familia declarada: Multilin.','/tecnologias/ge.svg');

-- Servicios: fichas técnicas v1 (10-oct-2026). Los servicios 5 y 6 figuran como pendientes de validación interna (validation_status = 'pending').
insert into services(title,slug,short_description,category_label,subtitle,description,problem,scope_items,scope_note,equipment_text,verification_items,verification_note,deliverable_items,applications_text,related_project_slugs,validation_status,editorial_status,sort_order,active) values ('Ingeniería de control y protección','ingenieria-control-proteccion','Desarrollamos ingeniería de control y protección para subestaciones eléctricas de media y alta tensión, incluyendo diseño de circuitos secundarios, planos eléctricos y documentación técnica para proyectos nuevos y modernizaciones.','Ingeniería eléctrica y sistemas secundarios','Ingeniería y documentación técnica de sistemas secundarios para subestaciones de media y alta tensión','IAC Ingenieros desarrolla soluciones de ingeniería orientadas a los sistemas de control y protección de subestaciones eléctricas, considerando los requerimientos funcionales, operativos y de seguridad de cada instalación.

El servicio comprende la elaboración, revisión y adecuación de documentación de ingeniería para tableros de control y protección, circuitos secundarios y sus interfaces con equipos primarios, tanto en proyectos nuevos como en ampliaciones y procesos de modernización tecnológica (retrofit).','Los sistemas de control y protección requieren diseños correctamente documentados y coordinados para asegurar su funcionamiento. Las inconsistencias en planos, conexiones, señalización o lógicas de control pueden provocar errores de montaje, dificultades en las pruebas, retrasos en la puesta en servicio y riesgos de operación.

El servicio permite disponer de una base de ingeniería verificable, reduciendo incertidumbres durante las etapas de construcción, pruebas y mantenimiento.',array['Relevamiento y evaluación de documentación eléctrica existente.','Desarrollo de ingeniería de circuitos de control, protección, señalización y supervisión.','Elaboración y actualización de diagramas eléctricos funcionales y de conexionado.','Diseño de circuitos secundarios asociados a interruptores, seccionadores, transformadores de medida e IED.','Elaboración de listas de señales, borneras, cables e interconexiones.','Diseño y adecuación de circuitos para ampliaciones y retrofit.','Revisión de interfaces entre tableros de control y protección y equipos de patio.','Actualización documental conforme a las modificaciones ejecutadas, cuando esté incluida en el contrato.']::text[],null,'Tableros de control y protección, relés de protección e IED, interruptores, seccionadores, transformadores de corriente y tensión, circuitos auxiliares AC/DC, borneras y cableado secundario.','{}'::text[],'Revisión de correspondencia entre diagramas, señales, funciones de control, conexiones y requerimientos del proyecto.',array['Diagramas eléctricos y de conexionado.','Planos de disposición y cableado de tableros, cuando correspondan.','Listas de cables, señales, borneras y materiales según alcance.','Documentación de ingeniería revisada.','Planos finales conforme a obra (as-built), cuando estén contratados.']::text[],'Subestaciones eléctricas de generación, transmisión, distribución y sistemas eléctricos industriales, en proyectos nuevos, ampliaciones y modernizaciones.',array['retrofit-tableros-subestacion-punutuma-69kv']::text[],'confirmed','publicado',1,true) on conflict (slug) do update set title=excluded.title, short_description=excluded.short_description, category_label=excluded.category_label, subtitle=excluded.subtitle, description=excluded.description, problem=excluded.problem, scope_items=excluded.scope_items, scope_note=excluded.scope_note, equipment_text=excluded.equipment_text, verification_items=excluded.verification_items, verification_note=excluded.verification_note, deliverable_items=excluded.deliverable_items, applications_text=excluded.applications_text, related_project_slugs=excluded.related_project_slugs, validation_status=excluded.validation_status, sort_order=excluded.sort_order;
insert into services(title,slug,short_description,category_label,subtitle,description,problem,scope_items,scope_note,equipment_text,verification_items,verification_note,deliverable_items,applications_text,related_project_slugs,validation_status,editorial_status,sort_order,active) values ('Diseño, armado y retrofit de tableros','tableros-armado-retrofit','Diseñamos, armamos, cableamos y modernizamos tableros de control y protección, incluyendo gabinetes asociados a transformadores y equipos eléctricos, desde la ingeniería hasta las verificaciones previas a su instalación.','Integración y construcción de sistemas secundarios',null,'IAC Ingenieros ofrece servicios especializados de diseño, armado, montaje, cableado y modernización de tableros de control y protección utilizados en subestaciones y otras instalaciones eléctricas.

El servicio incluye la integración de equipos y componentes secundarios de acuerdo con la ingeniería del proyecto, la identificación de circuitos, el ordenamiento de conexiones y la verificación funcional correspondiente.

En proyectos de retrofit, las actividades se orientan a reemplazar, adecuar o modernizar sistemas existentes, considerando la compatibilidad con los circuitos y equipos que continúan en operación.','El envejecimiento de equipos secundarios, la obsolescencia tecnológica, el deterioro del cableado y la necesidad de incorporar nuevas funciones pueden limitar la confiabilidad y mantenibilidad de una instalación.

Las intervenciones no planificadas también pueden ocasionar conexiones incorrectas, pérdida de señales, incompatibilidades o interrupciones prolongadas.

Este servicio permite ejecutar modernizaciones de manera documentada y técnicamente controlada.',array['Revisión de ingeniería y especificaciones de tableros.','Diseño de disposición y distribución interna de componentes.','Armado mecánico e instalación de equipos.','Montaje de relés, borneras, interruptores auxiliares y demás componentes secundarios.','Cableado interno, identificación y terminación de conductores.','Adecuación y reemplazo de componentes en tableros existentes.','Desmontaje, montaje y conexionado en sitio cuando corresponda.','Integración con equipos existentes de control y protección.','Inspección y verificación de conexiones.','Preparación de tableros para pruebas, despacho o instalación.','Elaboración de documentación final del montaje.']::text[],null,'Tableros de control, protección, transferencia y automatización; gabinetes de transformadores; IED; relés auxiliares; borneras; dispositivos de señalización; fuentes de alimentación; componentes de mando y circuitos secundarios.',array['Inspección visual y mecánica del montaje.','Verificación de continuidad y correspondencia de conexiones.','Revisión de identificación de equipos, cables y borneras.','Verificación de alimentación y encendido de componentes.','Pruebas funcionales del tablero cuando estén contempladas.','Pruebas de aceptación en taller (FAT), cuando sean contractualmente requeridas.']::text[],null,array['Tableros armados y cableados según ingeniería aprobada.','Registros de inspección y pruebas.','Planos y documentación de conexionado.','Relación de modificaciones ejecutadas.','Documentación conforme a obra, según contrato.']::text[],'Tableros nuevos, ampliaciones, reemplazo de sistemas secundarios, modernización de subestaciones y retrofit de instalaciones existentes.',array['retrofit-tableros-subestacion-punutuma-69kv','tableros-transformador-linea-automatizacion-sas-chaquilla','tableros-transformadores-se-velarde-69-10kv','retrofit-tableros-se-aranjuez-69kv','gabinete-transformador-t1290-se-qollpana']::text[],'proposed','publicado',2,true) on conflict (slug) do update set title=excluded.title, short_description=excluded.short_description, category_label=excluded.category_label, subtitle=excluded.subtitle, description=excluded.description, problem=excluded.problem, scope_items=excluded.scope_items, scope_note=excluded.scope_note, equipment_text=excluded.equipment_text, verification_items=excluded.verification_items, verification_note=excluded.verification_note, deliverable_items=excluded.deliverable_items, applications_text=excluded.applications_text, related_project_slugs=excluded.related_project_slugs, validation_status=excluded.validation_status, sort_order=excluded.sort_order;
insert into services(title,slug,short_description,category_label,subtitle,description,problem,scope_items,scope_note,equipment_text,verification_items,verification_note,deliverable_items,applications_text,related_project_slugs,validation_status,editorial_status,sort_order,active) values ('Configuración y pruebas de IED','configuracion-pruebas-ied','Realizamos configuración, parametrización y pruebas funcionales de relés de protección e IED, verificando sus funciones, señales y lógicas de operación de acuerdo con los requerimientos técnicos del proyecto.','Sistemas de protección eléctrica',null,'IAC Ingenieros desarrolla actividades especializadas de configuración, parametrización, diagnóstico y pruebas de dispositivos electrónicos inteligentes (IED) utilizados en sistemas de control y protección de subestaciones eléctricas.

El servicio contempla la revisión de configuraciones, verificación de entradas y salidas, comprobación de lógicas y ejecución de pruebas funcionales que permitan evaluar el comportamiento del dispositivo respecto de los criterios de operación establecidos.

Las pruebas se realizan considerando las funciones disponibles, el modelo del equipo y las especificaciones aplicables al proyecto.','Una configuración incorrecta, una lógica mal implementada, parámetros inconsistentes o problemas en las entradas y salidas de un IED pueden provocar operaciones indebidas o fallas de actuación del sistema de protección.

Estas condiciones pueden afectar la selectividad, disponibilidad y confiabilidad de la instalación.

El servicio permite detectar inconsistencias y verificar el comportamiento esperado antes de la entrada en operación o después de una modificación.',array['Identificación y revisión de características del IED.','Lectura, respaldo y análisis de configuraciones existentes.','Parametrización de funciones de protección y control conforme a ajustes aprobados.','Verificación de entradas y salidas binarias.','Verificación de funciones lógicas y señales asociadas.','Pruebas funcionales mediante equipos especializados.','Pruebas de inyección secundaria según las funciones contratadas.','Comprobación de señales de alarma, disparo y bloqueo, cuando corresponda.','Diagnóstico de eventos y registros de perturbaciones.','Verificación de funcionamiento después de ajustes o sustituciones.','Elaboración de protocolos de prueba y respaldos de configuración.']::text[],null,'Relés de protección e IED de fabricantes como ABB, Hitachi, Siemens, SEL y GE, según los modelos y capacidades técnicas disponibles.

Entre las familias identificadas en la información de IAC se encuentran ABB Relion, Siemens SIPROTEC, SEL y GE Multilin.',array['Pruebas de funciones de protección contratadas.','Verificación de señales de entrada y salida.','Pruebas de lógicas de disparo, bloqueo y alarma.','Comprobación de parámetros y configuración.','Pruebas secundarias con instrumentos adecuados.','Revisión de registros y eventos disponibles.']::text[],'Las pruebas de esquemas especiales, teleprotección y extremo a extremo requieren definir previamente equipos, metodología y alcance específico.',array['Protocolos e informes de prueba.','Archivos de configuración y respaldo, según permisos del cliente.','Registro de parámetros revisados o modificados.','Resultados de verificaciones funcionales.','Observaciones y recomendaciones técnicas.']::text[],'Puesta en servicio, modernización, sustitución de relés, mantenimiento de protecciones y verificación de sistemas secundarios en subestaciones de media y alta tensión.',array['retrofit-tableros-subestacion-punutuma-69kv']::text[],'proposed','publicado',3,true) on conflict (slug) do update set title=excluded.title, short_description=excluded.short_description, category_label=excluded.category_label, subtitle=excluded.subtitle, description=excluded.description, problem=excluded.problem, scope_items=excluded.scope_items, scope_note=excluded.scope_note, equipment_text=excluded.equipment_text, verification_items=excluded.verification_items, verification_note=excluded.verification_note, deliverable_items=excluded.deliverable_items, applications_text=excluded.applications_text, related_project_slugs=excluded.related_project_slugs, validation_status=excluded.validation_status, sort_order=excluded.sort_order;
insert into services(title,slug,short_description,category_label,subtitle,description,problem,scope_items,scope_note,equipment_text,verification_items,verification_note,deliverable_items,applications_text,related_project_slugs,validation_status,editorial_status,sort_order,active) values ('Comisionamiento y puesta en servicio','comisionamiento-puesta-en-servicio','Ejecutamos verificaciones, pruebas funcionales y actividades de comisionamiento de sistemas de control y protección, apoyando su integración y puesta en servicio en instalaciones eléctricas de media y alta tensión.','Pruebas y puesta en operación',null,'IAC Ingenieros participa en los procesos de precomisionamiento, comisionamiento y puesta en servicio de tableros y sistemas de control y protección en subestaciones eléctricas.

El servicio comprende la comprobación de instalaciones, conexiones, señales, funciones de mando y protección, así como la ejecución y documentación de las pruebas requeridas antes de su aceptación operativa.

Las actividades se coordinan con el propietario, operador y demás responsables del proyecto, respetando los procedimientos de seguridad y las condiciones de intervención autorizadas.','Durante la construcción, ampliación o modernización de una subestación pueden presentarse errores de cableado, incompatibilidades de configuración, señales incorrectas y funciones de control o protección que no operan conforme a lo previsto.

La falta de verificaciones estructuradas puede generar retrasos, reprocesos, indisponibilidad de equipos o condiciones inseguras durante la energización.

El comisionamiento permite comprobar que los sistemas intervenidos cumplen los requisitos funcionales establecidos antes de su aceptación.',array['Revisión de planos, documentación y protocolos de pruebas.','Inspección de tableros y circuitos secundarios instalados.','Verificación de continuidad y correspondencia de cableado.','Comprobación de circuitos auxiliares de alimentación.','Verificación de circuitos de mando, alarma, bloqueo y señalización.','Pruebas funcionales de interruptores y seccionadores a través de sus circuitos de control, cuando corresponda.','Verificación de interacción entre IED, tableros y equipos de patio.','Ejecución de pruebas secundarias y primarias según el alcance.','Registro y seguimiento de observaciones detectadas.','Participación en pruebas de aceptación en sitio (SAT).','Apoyo técnico durante maniobras y puesta en servicio autorizadas.','Preparación de documentación para entrega técnica.']::text[],null,'Tableros de control y protección, relés e IED, equipos de patio, circuitos secundarios, sistemas auxiliares e interfaces de control y señalización.

La inclusión de pruebas específicas de celdas de media tensión deberá definirse para cada proyecto.',array['Revisión del cableado y conexiones.','Pruebas funcionales de mando y señalización.','Verificación de alarmas, enclavamientos y disparos.','Comprobación de secuencias de operación.','Inyección secundaria o primaria cuando esté prevista.','Verificación integral de las funciones contratadas.']::text[],null,array['Protocolos de comisionamiento.','Resultados de pruebas.','Registro de observaciones y acciones correctivas.','Informe de actividades ejecutadas.','Documentación de aceptación técnica, según alcance.','Actualizaciones de ingeniería derivadas de las pruebas, cuando correspondan.']::text[],'Subestaciones nuevas, ampliaciones, modernizaciones, retrofit, sustitución de tableros y proyectos que requieran verificación antes de su incorporación al servicio.',array['retrofit-tableros-subestacion-punutuma-69kv','puesta-en-servicio-retrofit-telamayu-69kv','puesta-en-servicio-alimentador-pa01-colcapirhua','celdas-media-tension-24-9kv-se-central','celdas-media-tension-24-9kv-se-colcapirhua']::text[],'proposed','publicado',4,true) on conflict (slug) do update set title=excluded.title, short_description=excluded.short_description, category_label=excluded.category_label, subtitle=excluded.subtitle, description=excluded.description, problem=excluded.problem, scope_items=excluded.scope_items, scope_note=excluded.scope_note, equipment_text=excluded.equipment_text, verification_items=excluded.verification_items, verification_note=excluded.verification_note, deliverable_items=excluded.deliverable_items, applications_text=excluded.applications_text, related_project_slugs=excluded.related_project_slugs, validation_status=excluded.validation_status, sort_order=excluded.sort_order;
insert into services(title,slug,short_description,category_label,subtitle,description,problem,scope_items,scope_note,equipment_text,verification_items,verification_note,deliverable_items,applications_text,related_project_slugs,validation_status,editorial_status,sort_order,active) values ('Diagnóstico y mantenimiento','diagnostico-mantenimiento','Realizamos diagnóstico técnico y mantenimiento de sistemas de control y protección, orientados a detectar anomalías, verificar funciones y conservar condiciones adecuadas de operación.','Mantenimiento de sistemas de control y protección',null,'IAC Ingenieros propone servicios de inspección, diagnóstico y mantenimiento preventivo o correctivo de los sistemas secundarios de control y protección utilizados en instalaciones eléctricas.

El servicio se enfoca en evaluar el estado funcional de equipos y circuitos, identificar anomalías y definir acciones técnicas que contribuyan a mantener la disponibilidad y confiabilidad de los sistemas.

Las intervenciones deben planificarse conforme a las condiciones operativas y procedimientos de seguridad del cliente.','Los sistemas de control y protección pueden presentar fallas de hardware, conexiones defectuosas, anomalías de alimentación, errores de configuración o deterioro de componentes secundarios.

Estas condiciones pueden permanecer sin detectarse hasta que ocurre una operación indebida, una prueba fallida o una necesidad real de actuación.

El diagnóstico y mantenimiento permiten identificar condiciones anormales, corregir defectos y documentar el estado funcional de los equipos intervenidos.',array['Inspección técnica de tableros y sistemas secundarios.','Verificación del estado físico y funcional de equipos.','Revisión de conexiones, borneras y cableado de control.','Diagnóstico de alarmas y anomalías de IED.','Consulta y análisis de eventos y registros disponibles.','Revisión de respaldos y configuraciones, cuando corresponda.','Comprobación de señales, entradas y salidas.','Pruebas funcionales después de intervenciones.','Identificación de componentes defectuosos.','Ejecución de acciones correctivas aprobadas.','Elaboración de recomendaciones y prioridades de intervención.']::text[],null,'Relés de protección, IED, tableros de control y protección, circuitos auxiliares, relés auxiliares, borneras, fuentes y componentes secundarios asociados.',array['Comprobación de funciones críticas definidas por el cliente.','Verificación de alimentación, señales y conexiones.','Revisión de alarmas y diagnósticos internos.','Pruebas funcionales posteriores al mantenimiento.','Comparación de condiciones iniciales y finales, cuando existan mediciones disponibles.']::text[],null,array['Informe de diagnóstico.','Protocolos de mantenimiento y pruebas realizadas.','Registro de anomalías identificadas.','Detalle de correcciones efectuadas.','Recomendaciones técnicas.','Relación de actividades o repuestos pendientes.']::text[],'Mantenimiento programado, atención de fallas, modernizaciones, verificaciones posteriores a eventos y evaluación del estado de sistemas secundarios de subestaciones.','{}'::text[],'pending','publicado',5,true) on conflict (slug) do update set title=excluded.title, short_description=excluded.short_description, category_label=excluded.category_label, subtitle=excluded.subtitle, description=excluded.description, problem=excluded.problem, scope_items=excluded.scope_items, scope_note=excluded.scope_note, equipment_text=excluded.equipment_text, verification_items=excluded.verification_items, verification_note=excluded.verification_note, deliverable_items=excluded.deliverable_items, applications_text=excluded.applications_text, related_project_slugs=excluded.related_project_slugs, validation_status=excluded.validation_status, sort_order=excluded.sort_order;
insert into services(title,slug,short_description,category_label,subtitle,description,problem,scope_items,scope_note,equipment_text,verification_items,verification_note,deliverable_items,applications_text,related_project_slugs,validation_status,editorial_status,sort_order,active) values ('Automatización e integración','automatizacion-integracion','Desarrollamos soluciones de ingeniería y tableros de automatización para la integración de señales y funciones de control en instalaciones eléctricas, conforme a los requerimientos técnicos de cada proyecto.','Automatización de sistemas eléctricos',null,'IAC Ingenieros contempla servicios de ingeniería e integración de tableros y sistemas de automatización asociados al control de instalaciones eléctricas.

El objetivo es establecer interfaces funcionales entre equipos de campo, tableros de control y dispositivos de automatización, de acuerdo con la arquitectura y las condiciones técnicas definidas para cada proyecto.

La incorporación de sistemas SCADA, RTU, gateways, comunicaciones industriales o protocolos específicos deberá validarse previamente como parte del alcance ofrecido.','En instalaciones con equipos de diferentes tecnologías pueden presentarse dificultades para incorporar nuevas señales, ampliar funciones de control o integrar tableros existentes con sistemas de supervisión.

La ausencia de una ingeniería de interfaces claramente definida puede generar errores de conexión, señales inconsistentes y dificultades de diagnóstico.

El servicio busca facilitar la integración ordenada y verificable de las funciones de automatización contratadas.',array['Revisión de necesidades funcionales de automatización.','Diseño de interfaces y circuitos secundarios.','Elaboración de listas de señales de entrada y salida.','Diseño y armado de tableros de automatización.','Instalación y conexionado de dispositivos.','Adecuación de circuitos de mando y supervisión.','Integración física de señales entre equipos y tableros.','Verificación de correspondencia de señales.','Pruebas funcionales de entradas, salidas y mandos.','Elaboración de documentación y planos finales.']::text[],'La integración mediante redes, protocolos de comunicación y plataformas de supervisión se incorporará únicamente después de confirmar las capacidades técnicas correspondientes.','Tableros de automatización, dispositivos de control, módulos de entradas y salidas, borneras, circuitos secundarios y equipos de interfaz.

Otros dispositivos de comunicación o supervisión se definirán según las especificaciones y capacidades confirmadas.',array['Inspección y continuidad de conexiones.','Verificación de señales digitales y analógicas, según diseño.','Comprobación de entradas y salidas.','Pruebas funcionales de mandos y señalización.','Revisión de correspondencia entre planos y conexiones.']::text[],null,array['Planos eléctricos y de conexionado.','Listas de señales.','Tableros y circuitos integrados según contrato.','Registros de pruebas funcionales.','Informe de implementación.','Documentación final del sistema instalado, según alcance.']::text[],'Modernización de sistemas de control, integración de tableros, ampliación de señales y proyectos de automatización de instalaciones eléctricas.',array['tableros-transformador-linea-automatizacion-sas-chaquilla']::text[],'pending','publicado',6,true) on conflict (slug) do update set title=excluded.title, short_description=excluded.short_description, category_label=excluded.category_label, subtitle=excluded.subtitle, description=excluded.description, problem=excluded.problem, scope_items=excluded.scope_items, scope_note=excluded.scope_note, equipment_text=excluded.equipment_text, verification_items=excluded.verification_items, verification_note=excluded.verification_note, deliverable_items=excluded.deliverable_items, applications_text=excluded.applications_text, related_project_slugs=excluded.related_project_slugs, validation_status=excluded.validation_status, sort_order=excluded.sort_order;


insert into projects(title,slug,description,location,voltage_level,voltages,installation_type,services_done,client_display_name,year,project_date,period_label,cover_image,department,technologies,source_note,validation_status,featured,active) values ('Tableros armados para el laboratorio de Elfec 115/24,9 kV','tableros-laboratorio-elfec-115-24-9kv','Tableros armados para el laboratorio de Elfec 115/24,9 kV.
Período: 2021.
